<?php
require __DIR__.'/app/bootstrap.php';

$userId=require_auth();$tripId=(int)($_GET['id']??$_POST['trip_id']??0);if($tripId<1){http_response_code(400);exit('Trip is required.');}
$service=new TripAffordabilityService(db());$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        if(!$service->ready())throw new RuntimeException('Run System Upgrade for Budget-Aware Trip Planning + Affordability Intelligence.');
        $action=(string)($_POST['action']??'');
        if($action==='save_settings'){$service->saveSettings($userId,$tripId,$_POST);flash('success','Affordability assumptions updated.');}
        elseif($action==='save_scenario'){$service->saveScenario($userId,$tripId,$_POST);flash('success','Comparison scenario saved.');}
        elseif($action==='delete_scenario'){$service->deleteScenario($userId,$tripId,(int)($_POST['scenario_id']??0));flash('success','Comparison scenario removed.');}
        else throw new InvalidArgumentException('Unknown affordability action.');
        redirect('trip-affordability.php?id='.$tripId);
    }catch(InvalidArgumentException|DomainException|OutOfBoundsException $e){$error=$e->getMessage();}
    catch(Throwable $e){error_log('Affordability update failed: '.$e->getMessage());$error='Vacation Brain could not update affordability planning safely.';}
}
try{$snapshot=$service->snapshot($userId,$tripId);}catch(OutOfBoundsException){http_response_code(404);exit('Trip not found.');}
$trip=$snapshot['trip'];$forecast=$snapshot['forecast']??[];$owner=!empty($snapshot['can_manage']);$canView=!empty($snapshot['can_view']);$success=flash('success');$title='Affordability — '.$trip['name'];$pageStyles=['assets/trip-affordability.css'];$currency=(string)($trip['currency']??'USD');
function vb_aff_money(mixed $v,string $currency):string{if($v===null||$v==='')return '—';return ($currency==='USD'?'$':$currency.' ').number_format((float)$v,2);}
function vb_aff_label(string $v):string{return ucwords(str_replace('_',' ',$v));}
require __DIR__.'/partials/header.php';
?>
<section class="vb-aff-page"><div class="shell vb-aff-shell">
<header class="vb-aff-head"><div><a class="back-link" href="<?=e(app_url('dream-trip.php?id='.$tripId.'&workspace=affordability'))?>">← Trip workspace</a><span class="eyebrow">Budget-Aware Trip Planning</span><h1>Can this trip fit the budget without ruining the trip?</h1><p>Vacation Brain combines saved booking values, category plans, saved provider estimates and role-appropriate cost history into a planning forecast. It never treats an estimate as a quote or a booking value as bank settlement.</p></div><div class="vb-aff-head-actions"><a class="button secondary" href="<?=e(app_url('trip-cost.php?id='.$tripId))?>">True Trip Economics</a><a class="button secondary" href="<?=e(app_url('dream-trip.php?id='.$tripId))?>">Trip Plan</a></div></header>
<?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<?php if(!$snapshot['ready']):?><div class="alert error"><strong>Affordability Intelligence needs migration 060 / app v1.52.</strong> <?php if(is_admin()):?><a href="<?=e(app_url('upgrade.php'))?>">Run System Upgrade</a><?php endif;?></div><?php endif;?>
<div class="vb-aff-notice"><strong>No hidden FX and no financial execution.</strong> Currency buckets never convert implicitly. This page cannot pay, book, cancel, modify reservations, submit claims, request refunds, redeem credits, open checkout or mutate a provider.</div>
